public class Main {
    static IO io;

    public static void main(String[] args) throws Exception {

        io = new IO("B-small-attempt1");
        int t = io.nextInt();
        for (int i = 0; i < t; i++) {
            io.nextCase();
            solve();
        }
        io.flush();
    }

    public static void solve() {
        int b = io.nextInt();
        int n = io.nextInt();
        int[] m = io.nextIntArray(b);
        long left = -1;
        long right = 100000L * 1000000000L * 2L;
        int n2 = Math.max(n-b, 0);
        while (left + 1 < right) {
            long center = (left + right) / 2;
            long sum = 0;
            for (int i = 0; i < b; i++) {
                sum += center / m[i];
            }
            if (sum >= n2) {
                right = center;
            }else{
                left = center;
            }
        }
        long time = right;
        PriorityQueue<Barber> pq = new PriorityQueue<>();
        for(int i=0;i<b;i++) {
            pq.add(new Barber(time / m[i] * m[i], i));
            n -= time / m[i];
        }
        for(int i=0;i<n-1;i++) {
            Barber bb = pq.poll();
            bb.endTime += m[bb.id];
            pq.add(bb);
        }
        io.println(pq.peek().id + 1);
    }

    static class Barber implements Comparable<Barber>{
        long endTime;
        int id;
        public Barber(long endTime,int id) {
            this.endTime = endTime;
            this.id = id;
        }
        public int compareTo(Barber o) {
            if (endTime != o.endTime) {
                return Long.compare(endTime, o.endTime);
            }
            return Integer.compare(id, o.id);
        }
    }

 }

