public class Main {
    static IO io;
    public static void main(String[] args) throws Exception {

        io = new IO("B-small-attempt1.in","B-small-attempt1.out");
        int t = io.nextInt();
        for(int i=0;i<t;i++) {
            io.nextCase();
            solve();
        }
        io.flush();
    }
    public static void solve() {
        int d = io.nextInt();
        int[] p = io.nextIntArray(d);
        int ans = Integer.MAX_VALUE;
        for(int i=1;i<=1000;i++) {
            int sum = 0;
            for(int j=0;j<d;j++) {
                sum += (p[j] - 1) / i;
            }
            ans = Math.min(ans, sum + i);
        }
        io.println(ans);
    }

 }
