public class Main {
     private static StringTokenizer st;
     private static BufferedReader br;
     public static long MOD = 1000000007;

     public static void print(Object x) {
         System.out.println(x + "");
     }
     public static void printArr(long[] x) {
         StringBuilder s = new StringBuilder();
         for (int i = 0; i < x.length; i++) {
             s.append(x[i] + " ");
         }
         print(s);
     }
     public static void printArr(int[] x) {
         StringBuilder s = new StringBuilder();
         for (int i = 0; i < x.length; i++) {
             s.append(x[i] + " ");
         }
         print(s);
     }
     public static void printArr(char[] x) {
         StringBuilder s = new StringBuilder();
         for (int i = 0; i < x.length; i++) {
             s.append(x[i] + "");
         }
         print(s);
     }
     public static String join(Collection<?> x, String space) {
         if (x.size() == 0) return "";
         StringBuilder sb = new StringBuilder();
         boolean first = true;
         for (Object elt : x) {
             if (first) first = false;
             else sb.append(space);
             sb.append(elt);
         }
         return sb.toString();
     }

     public static String nextToken() throws IOException {
         while (st == null || !st.hasMoreTokens()) {
             String line = br.readLine();
             st = new StringTokenizer(line.trim());
         }
         return st.nextToken();
     }
     public static int nextInt() throws IOException {
         return Integer.parseInt(nextToken());
     }
     public static long nextLong() throws IOException {
         return Long.parseLong(nextToken());
     }

     public static void main(String[] args) throws IOException {

         br = new BufferedReader(new FileReader("input.txt"));

         int T = nextInt();
         for (int t = 1; t <= T; t++) {
             long n = nextInt();
             if (n == 0) {
                 System.out.printf("Case #%d: INSOMNIA%n", t);
             } else {
                 Set<Long> digits = new HashSet<>();
                 long i = 1;
                 while (true) {
                     long cur = i * n;
                     while (cur > 0) {
                         digits.add(cur % 10);
                         cur /= 10;
                     }
                     if (digits.size() == 10) break;
                     i += 1;
                 }
                 System.out.printf("Case #%d: %d%n", t, i * n);
             }
         }
     }
 }
