            }
            long min = -1;
            long max = 1L << 50;
            while(min != max) {
                long mid = (min+max)/2;
                if(min == mid) mid++;
                if(numCut(list, mid) >= want) {
                    max = mid-1;
                }
                else {
                    min = mid;
                }
            }
            long cut = numCut(list, min);
            for(int a = 0; a < n; a++) {
                if((min+1)%list[a] == 0) {
                    if(++cut == want) {
                        pw.println(a+1);
                        break;
                    }
                }
            }
        }
        pw.close();
    }

    public static long numCut(int[] list, long time) {
        long ret = 0;
        for(int out: list) {
            ret += (time / out) + 1;
            if(ret >= Integer.MAX_VALUE) break;
        }
        return ret;
    }

