        for (int i=0;i+K<=L;i++){
            char c=mem[i];
            if (c=='-'){
                cnt++;
                for (int u=0;u<K;u++){
                    mem[u+i]=inv(mem[u+i]);
                }
            }
        }

        for (int i=L-K+1;i<L;i++){
            char c=mem[i];
            if (c=='-')
                return res;
        }
        res=""+cnt;
        return res;
    }


