    static void process() throws Exception {
        Locale.setDefault(Locale.US);


        File inputFile=new File("B.in");
        PrintWriter outputFile= new PrintWriter("B.out","UTF-8");
        Scanner sc=new Scanner(inputFile);
        sc.useLocale(Locale.US);



        int T=sc.nextInt();
        for (int t=1;t<=T;t++){

            int AC=sc.nextInt();
            int AJ=sc.nextInt();
            int[][] time=new int[2][LX];
            for (int i=0;i<AC;i++){
                int st=sc.nextInt();
                int en=sc.nextInt();
                for (int u=st;u<en;u++)
                    time[0][u]=1;
            }

            for (int i=0;i<AJ;i++){
                int st=sc.nextInt();
                int en=sc.nextInt();
                for (int u=st;u<en;u++)
                    time[1][u]=1;
            }

            int[][][] num=new int[2][2][DX+1];
            for (int f=0;f<2;f++)
            for (int e=0;e<2;e++)
                Arrays.fill(num[f][e],MX);
            for (int e=0;e<2;e++){
                if (time[e][0]==0)
                    num[e][e][0]=0;
            }

            for (int u=0;u<LX;u++){
                int[][][] nxt=new int[2][2][DX+1];
                for (int f=0;f<2;f++)
                for (int e=0;e<2;e++)
                    Arrays.fill(nxt[f][e],MX);
                for (int f=0;f<2;f++)
                for (int e=0;e<2;e++)
                    for (int tim=0;tim<=DX;tim++){
                        if (num[f][e][tim]!=MX){





                            if (e==0){
                                if (tim+1<=DX && time[e][u]==0){

                                    nxt[f][e][tim+1]=Math.min(nxt[f][e][tim+1],num[f][e][tim]);
                                }
                            } else {
                                if (u+1-tim<=DX && time[e][u]==0){

                                    nxt[f][e][tim]=Math.min(nxt[f][e][tim],num[f][e][tim]);
                                }
                            }


                            if (e==0){
                                if (u+1-tim<=DX && time[1-e][u]==0){

                                    nxt[f][1-e][tim]=Math.min(1+num[f][e][tim],nxt[f][1-e][tim]);
                                }
                            } else {
                                if (1+tim<=DX && time[1-e][u]==0){

                                    nxt[f][1-e][1+tim]=Math.min(1+num[f][e][tim],nxt[f][1-e][1+tim]);
                                }
                            }
                        }
                    }


                num=nxt;

            }
            int min=MX;
            for (int f=0;f<2;f++)
                for (int e=0;e<2;e++){
                    int x=num[f][e][DX];
                    if (x!=MX){
                        if (f!=e)
                            x++;
                    }
                    min=Math.min(min, x);
                }









            String ss=""+min;
            System.out.println("Case #"+t+": "+ss);
            outputFile.println("Case #"+t+": "+ss);


        }



        sc.close();
        outputFile.close();


    }



    public static void main(String[] args) throws Exception {


        process();


    }






 }
