         private String token;

         public Solver(int caseNumber) {
             this.caseNumber = caseNumber;
         }

         public String solve() throws Exception {
             debug("solving case %d", caseNumber);
             int maxShy = getInt();
             token = getToken();
             assert token.length() == maxShy + 1;

             if (works(0)) {
                 return "0";
             }
             int min = 0;
             int max = 1;
             while (true) {
                 if (works(max)) {
                     break;
                 }
                 min = max + 1;
                 max *= 2;
             }
             while (min < max) {
                 int middle = (min + max) / 2;
                 if (works(middle)) {
                     max = middle;
                 } else {
                     min = middle + 1;
                 }
             }
             return "" + min;
         }

         private boolean works(int clapping) {
             for (int shyness = 0; shyness < token.length(); shyness++) {
                 int numPeople = token.charAt(shyness) - '0';
                 if (clapping < shyness) {
                     return false;
                 }
                 clapping += numPeople;
             }
             return true;
         }
     }
 }
