                     rooks[r][c] = true;
                     break;
                 case "o":
                     bishops[r][c] = true;
                     rooks[r][c] = true;
                     break;
             }
         }
         {
             boolean[] row = new boolean[n];
             boolean[] col = new boolean[n];
             int res = n;
             for (int i = 0; i < n; i++) {
                 for (int j = 0; j < n; j++) {
                     if (rooks[i][j]) {
                         row[i] = true;
                         col[j] = true;
                         res--;
                     }
                 }
             }
             int r = 0;
             int c = 0;
             for (int i = 0; i < res; i++) {
                 while (row[r]) r++;
                 while (col[c]) c++;
