                     if (bishops[i][j]) {
                         int ii = i + j;
                         int jj = i - j + n - 1;
                         d1[ii] = true;
                         d2[jj] = true;
                     }
                 }
             }
             for (int i = 0; i < n; i++) {
                 for (int j = 0; j < n; j++) {
                     int ii = i + j;
                     int jj = i - j + n - 1;
                     if (!d1[ii] && !d2[jj]) {
                         a[ii][jj] = true;
                     }
                 }
             }
             for (int i = 0; i < nn; i++) {
                 Arrays.fill(z, false);
                 dfs(i);
             }
             for (int jj = 0; jj < nn; jj++) {
                 if (p[jj] >= 0) {
                     int ii = p[jj];
                     int i = (ii + jj - (n - 1)) / 2;
                     int j = ii - i;
                     changed[i][j] = true;
                     bishops[i][j] = true;
                 }
             }
         }
         int ans = 0;
