                 if (changed[i][j]) {
                     res.append("\n");
                     if (rooks[i][j] && bishops[i][j]) {
                         res.append("o");
                     } else if (rooks[i][j]) {
                         res.append("x");
                     } else if (bishops[i][j]) {
                         res.append("+");
                     }
                     res.append(" ").append(i + 1).append(" ").append(j + 1);
                 }
             }
         }
         return res.toString();
