public class C {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    class UnionFindTree {
        int[] count;
        int[] parent;

        public UnionFindTree(int n) {
            count = new int[n];
            parent = new int[n];
            for (int i = 0; i < parent.length; i++) {
                parent[i] = i;
                count[i] = 1;
            }
        }

        public int cntUpdate(int x) {
            if (parent[x] == x) return count[x];
            return count[x] = cntUpdate(parent[x]);
        }

        public int find(int x) {
            if (parent[x] == x) return x;
            return parent[x] = find(parent[x]);
        }

        public boolean same(int x, int y) {
            return find(x) == find(y);
        }

        public void unite(int x, int y) {
            int xx = find(x), yy = find(y);
            if (xx == yy) return;
            parent[xx] = yy;
            int tmp = count[xx];
            count[xx] += count[yy];
            count[yy] += tmp;
        }

        public String toString() {
            return Arrays.toString(parent);
        }
    }

    class Pair implements Comparable<Pair> {
        int a;
        int b;
        double dist;

        Pair (int a, int b, double dist) {
            this.a = a;
            this.b = b;
            this.dist = dist;
        }

        public int compareTo(Pair s) {
            return Double.compare(dist, s.dist);    
        }

        public String toString() {
            return a + " " + b + " " + dist;
        }
    }

    double calcDist(double x1, double y1, double z1, double x2, double y2, double z2) {
        double dx = x1 - x2;
        double dy = y1 - y2;
        double dz = z1 - z2;
        return Math.sqrt(dx * dx + dy * dy + dz * dz);
    }

    public void run() {
        int T = in.nextInt();
        for (int caseN = 1; caseN <= T; caseN++) {
            int N = in.nextInt(), S = in.nextInt();
            int[] xs = new int[N], ys = new int[N], zs = new int[N];
            int[] vxs = new int[N], vys = new int[N], vzs = new int[N];
            for (int i = 0; i < N; i++) {
                xs[i] = in.nextInt();
                ys[i] = in.nextInt();
                zs[i] = in.nextInt();
                vxs[i] = in.nextInt();
                vys[i] = in.nextInt();
                vzs[i] = in.nextInt();
            }

            UnionFindTree uft = new UnionFindTree(N);
            PriorityQueue<Pair> pq = new PriorityQueue<>();
            for (int i = 0; i < N; i++) {
                for (int j = i + 1; j < N; j++) {
                    pq.add(new Pair(i, j, calcDist(xs[i], ys[i], zs[i], xs[j], ys[j], zs[j])));
                }
            }

            double res = 0;
            while (!pq.isEmpty() && !uft.same(0, 1)) {
                Pair p = pq.poll();
                res = p.dist;
                uft.unite(p.a, p.b);                
            }

            out.println("Case #" + caseN + ": " + res);
        }
        out.close();
    }

