     static class TaskA {
         public void solve(int testNumber, Scanner in, PrintWriter out) {
             int n = in.nextInt();
             int[] count = new int[n];
             int partiesLeft = n;
             for (int i = 0; i < n; i++) count[i] = in.nextInt();
             int senators = 0;
             for (int s : count) senators += s;
             ArrayList<Integer> largest = new ArrayList<>();
             int best;
             out.printf("Case #%d: ", testNumber);
             while (senators > 0) {
                 best = 0;
                 largest.clear();
                 for (int i = 0; i < n; i++) {
                     if (count[i] > best) {
                         largest.clear();
                         best = count[i];
                         largest.add(i);
                     } else if (count[i] == best) {
                         largest.add(i);
                     }
                 }
                 String s = "" + toChar(largest.get(0));
                 count[largest.get(0)]--;
                 senators--;
                 if (largest.size() == 2) {
                     s += toChar(largest.get(1));
                     count[largest.get(1)]--;
                     senators--;
                 }
                 out.print(s + " ");
             }
             out.println();
         }

         public char toChar(int a) {
             return (char) ('A' + a);
         }

     }
 }

