        int pp=0;
        for(int j=0;j<J;j++)for(int p=0;p<P;p++)for(int s=0;s<S;s++){
            A[pp][0]=j;A[pp][1]=p;A[pp][2]=s;
            pp++;
        }
        int bm=0;
        if(J==3){
            if(K==1)return print(22102794,all);
            if(K==2)return print(62580637,all);
            return print((1<<all)-1,all);
        }
