 public class A {


    private static final String fileName = "results/con2015/con2015R1a/"+A.class.getSimpleName().toLowerCase();
    private static final String inputFileName = fileName + ".in";
    private static final String outputFileName = fileName + ".out";
    private static InputReader in;
    private static OutputWriter out;

    private void solve() {
        int N = in.readInt();
        long A = 0, B = 0;
        int[] ns = new int[N];
        for (int i = 0; i < N; i++) {
            ns[i] = in.readInt();
        }

        int rate = 0;
        for(int i=1;i<N;i++){
            if(ns[i] < ns[i-1]){
                A += ns[i-1]-ns[i];
                rate = Math.max(rate, ns[i-1]-ns[i]);
            }
        }

        for(int i=0;i+1<N;i++){
            B += Math.min(ns[i],rate);
        }
        out.printLine(A+" "+B);
    }
