 class TaskA {
     public void solve(int testNumber, InputReader in, PrintWriter out) {
         int length = in.nextInt();
         char input[] = in.next().toCharArray();

         int sum = 0;
         int add = 0;
         for (int i=0; i<=length; i++){
             int p = input[i] - '0';
             if (p != 0){
                 if (sum < i){
                     add += i-sum;
                     sum += i-sum;
                 }
                 sum += p;
             }
         }
         out.println("Case #"+testNumber+": " + add);
     }
