public class Codejam {
    public static long[] equat(long x1, long y1, long x2, long y2) {
        long[] ret = new long[3];
        if (x1 == x2) {
            ret[0] = 1;
            ret[2] = - x1;
            return ret;
        }
        if (y1 == y2) {
            ret[1] = 1;
            ret[2] = -y1;
            return ret;
        }
        ret[0] = y2 - y1;
        ret[1] = x1 - x2;
        ret[2] = (y2 - y1) * (-x1) + y1 * (x2 - x1);
        return ret;
