        for(int tt = 1; tt <= T; tt++){
            final int R = sc.nextInt();
            final int C = sc.nextInt();

            final char[][] input = new char[R][];
            for(int i = 0; i < R; i++){
                input[i] = sc.next().toCharArray();
            }

            while(true){
                boolean updated = false;
                for(int i = 0; i < R; i++){
                    for(int j = 0; j < C; j++){
                        if(input[i][j] != '?'){ continue; }

                        if(i != 0 && input[i - 1][j] != '?'){
                            input[i][j] = input[i - 1][j];
                            updated = true;
                        }
                    }
                }

                for(int i = R - 1; i >= 0; i--)
                    for(int j = C - 1; j >= 0; j--){
                    if(input[i][j] != '?'){ continue; }

                    if(i != R - 1 && input[i + 1][j] != '?'){
                        input[i][j] = input[i + 1][j];
                        updated = true;
                    }
                }

                if(!updated){ break; }
            }

            while(true){
                boolean updated = false;
                for(int i = 0; i < R; i++){
                    for(int j = 0; j < C; j++){
                        if(input[i][j] != '?'){ continue; }

                        if(j != 0 && input[i][j - 1] != '?'){
                            input[i][j] = input[i][j - 1];
                            updated = true;
                        }
                    }
                }

                for(int i = R - 1; i >= 0; i--)
                    for(int j = C - 1; j >= 0; j--){
                    if(input[i][j] != '?'){ continue; }

                    if(j != C - 1 && input[i][j + 1] != '?'){
                        input[i][j] = input[i][j + 1];
                        updated = true;
                    }
                }

                if(!updated){ break; }
            }

            System.out.printf("Case #%d:\n", tt);
            for(int i = 0; i < R; i++){
                for(int j = 0; j < C; j++){
                    System.out.print(input[i][j]);
                }
                System.out.println();
            }

        }
    }

