 @SuppressWarnings("unchecked")
 public class B {

     private static final String NO = "IMPOSSIBLE";
     public static final long MAX = Long.MAX_VALUE;
     public static final int INF = 1000000000;
     public static final int MOD = 9901; 
     public static final int UNDEF = -3;



     private void run(int caseNumber) throws Exception {
         int B = INT();
         int N = INT();
         long[] m = new long[B];
         for (int i = 0; i < m.length; i++) {
             m[i] = INT();
         }



         if(debugTestCases.length>0 && Arrays.binarySearch(debugTestCases, caseNumber)<0) {
             if(writeToFile) {
                 out.printf("Case #%d: skip\n", caseNumber);
             }

             return;
         }



         long lcm=lcm(m);
         long block=0;
         for (int i = 0; i < m.length; i++) {
             block+=lcm/m[i];
         }
         N--;
         if (N>block) {
             N%=block;
         }
         int ret = bf(N,m);


         out.printf("Case #%d: %s\n", caseNumber, ret);


     }

     private int bf(int n, long[] m) {

         PriorityQueue<XY> q = new PriorityQueue<>();
         for (int i = 0; i < m.length; i++) {
             q.add(new XY(0,i));
         }
         int i=0;
         while (true) {
             XY st = q.poll();
             long t=st.x;
             long idx=st.y;
             if (i==n) {
                 return (int) idx+1;
             }

             q.add(new XY(t+m[(int) idx], idx));
             i++;
         }
     }
     static class XY implements Comparable<XY> {
         long x;
         long y;

         public XY(long x, long y) {
             this.x = x;
             this.y = y;
         }

         public String toString() {
             return "(" + x + ", " + y + ")";
         }

         public int hashCode() {
             final long M = 31;
             long r = M * M + M * x + y;
             return (int) r;
         }

         public boolean equals(Object a) {
             if (a == null || getClass() != a.getClass())
                 return false;
             XY o = (XY) a;
             return x == o.x && y == o.y;
         }

         public int compareTo(XY o) {

             if (x != o.x)
                 return x < o.x ? -1 : 1;
             return y < o.y ? -1 : (y == o.y ? 0 : 1);
         }
     }


     public static long lcm(long a, long b) {

         return b / gcd(a, b) * a; 
     }

     public static long lcm(long[] a) {
         long ret = 1;
         for (int i = 0; i < a.length; ++i) {
             ret = lcm(a[i], ret);


         }
         return ret;
     }


     public static long gcd(long x, long y) {
         x = Math.abs(x); 
         y = Math.abs(y);
         if (x == 0 && y == 0)
             return 1;
         while (y != 0) {
             long c = x % y;
             x = y;
             y = c;
         }
         return x;
     }


     public static long gcd(long[] x) {
         long ret = x[0];
         for (int i = 1; i < x.length; ++i) {
             ret = gcd(ret, x[i]);
         }
         return ret;
     }

