     double binSearch(int D, XY[] a) {
         double res = 0;


         double lo = 0;
         double hi = INF;
         while (lo + EPS < hi) {
             double mid = (double) (lo + hi) / 2;
             if (eq(mid, hi) || eq(mid, lo))
                 break;

             if (ok(mid, a, D)) {
                 lo = mid;
             } else {
                 hi = mid;
             }
         }
         res = (lo + hi) / 2;
