 class TaskB {
     public void solve(int testNumber, InputReader in, OutputWriter out) {
         int rowCount = in.readInt();
         int columnCount = in.readInt();
         int total = rowCount * columnCount;
         int peopleCount = in.readInt();
         int answer = 0;
         if (peopleCount > total / 2 + total % 2) {
             boolean[][] board = new boolean[rowCount][columnCount];
             for (int i = peopleCount + 1; i <= total; i++) {
                 int removeRow = 0, removeColumn = 0, maxi = 0;
                 for (int r = 0; r < rowCount; r++) {
                     for (int c = 0; c < columnCount; c++) {
                         if (board[r][c]) continue;
                         int conn = 0;
                         if (r > 0 && !board[r - 1][c]) {
                             conn++;
                         }
                         if (r + 1 < rowCount && !board[r + 1][c]) {
                             conn++;
                         }
                         if (c > 0 && !board[r][c - 1]) {
                             conn++;
                         }
                         if (c + 1 < columnCount && !board[r][c + 1]) {
                             conn++;
                         }
                         if (conn > maxi) {
                             maxi = conn;
                             removeRow = r;
                             removeColumn = c;
                         }
                     }
                 }
                 board[removeRow][removeColumn] = true;
             }
             for (int r = 0; r < rowCount; r++) {
                 for (int c = 0; c < columnCount; c++) {
                     if (board[r][c]) continue;
                     if (r + 1 < rowCount && !board[r + 1][c]) {
                         ++answer;
                     }
                     if (c + 1 < columnCount && !board[r][c + 1]) {
                         ++answer;
                     }
                 }
             }
         }
         out.printLine("Case #" + testNumber + ": " + answer);
     }
 }

 class InputReader {

     private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

     public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

     public String readString() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        StringBuilder res = new StringBuilder();
        do {
            if (Character.isValidCodePoint(c))
                res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

     public String next() {
        return readString();
    }

     public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }
 }

 class OutputWriter {
    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

     public void print(Object...objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i != 0)
                writer.print(' ');
            writer.print(objects[i]);
        }
    }

     public void printLine(Object...objects) {
        print(objects);
        writer.println();
    }

     public void close() {
        writer.close();
    }

 }

