        while (pos > 0) {
            char best = s.charAt(0);
            int bestPos = 0;
            for (int i = 1; i < pos; i++) {
                if (s.charAt(i) >= best) {
                    best = s.charAt(i);
                    bestPos = i;
                }
            }
            prefix.append(best);
            for (int i = pos - 1; i > bestPos; i--)
                suffix.append(s.charAt(i));
            pos = bestPos;
        }
        String ans = prefix.append(suffix.reverse()).toString();
        out.write(ans);
    }

