public class Main {
     public static void main(String[] args) {
         Locale.setDefault(Locale.US);
         InputStream inputStream;
         try {
             final String regex = "B-(small|large).*[.]in";
             File directory = new File(".");
             File[] candidates = directory.listFiles(new FilenameFilter() {
                 public boolean accept(File dir, String name) {
                     return name.matches(regex);
                 }
             });
             File toRun = null;
             for (File candidate : candidates) {
                 if (toRun == null || candidate.lastModified() > toRun.lastModified()) {
                     toRun = candidate;
                 }
             }
             inputStream = new FileInputStream(toRun);
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         OutputStream outputStream;
         try {
             outputStream = new FileOutputStream("b.out");
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         InputReader in = new InputReader(inputStream);
         OutputWriter out = new OutputWriter(outputStream);
         TaskB solver = new TaskB();
         solver.solve(1, in, out);
         out.close();
     }

     static class TaskB {
         static final int BUBEN = 4000;
         double[][] c = new double[101][101];
         Random r = new Random(239);

         public void solve(int testNumber, InputReader in, OutputWriter out) {
             for (int i = 0; i <= 100; i++) {
                 c[i][0] = 1;
                 for (int j = 1; j <= i; j++) {
                     c[i][j] = c[i - 1][j - 1] + c[i - 1][j];
                 }
             }
             Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
                 int n;
                 int[] prerequisite;
                 char[] label;
                 int m;
                 String[] words;


                 public void read(InputReader in) {
                     n = in.readInt();
                     prerequisite = IOUtils.readIntArray(in, n);
                     label = IOUtils.readCharArray(in, n);
                     m = in.readInt();
                     words = IOUtils.readStringArray(in, m);
                 }

                 double[] answer;

                 double[] ways;
                 int[] length;
                 Graph graph;


                 public void solve() {
                     answer = new double[m];
                     ways = new double[n];
                     length = new int[n];
                     Arrays.fill(ways, -1);
                     graph = new Graph(n);
                     for (int i = 0; i < n; i++) {
                         if (prerequisite[i] != 0) {
                             graph.addSimpleEdge(prerequisite[i] - 1, i);
                         }
                     }
                     for (int i = 0; i < n; i++) {
                         calculate(i);
                     }
                     boolean[] done = new boolean[n];
                     double[] cWays = new double[n];
                     for (int i = 0; i < BUBEN; i++) {
                         Arrays.fill(done, false);
                         StringBuilder builder = new StringBuilder(n);
                         for (int j = 0; j < n; j++) {
                             double total = 0;
                             for (int k = 0; k < n; k++) {
                                 if (done[k] || prerequisite[k] != 0 && !done[prerequisite[k] - 1]) {
                                     cWays[k] = 0;
                                 } else {
                                     int cLength = 0;
                                     double kWays = 1;
                                     for (int l = 0; l < n; l++) {
                                         if (!(done[l] || k == l || prerequisite[l] != 0 && prerequisite[l] != k + 1 &&
                                                 !done[prerequisite[l] - 1])) {
                                             kWays *= ways[l];
                                             kWays *= c[cLength + length[l]][cLength];
                                             cLength += length[l];
                                         }
                                     }
                                     cWays[k] = kWays;
                                 }
                                 total += cWays[k];
                             }
                             double result = total * r.nextDouble();
                             for (int k = 0; k < n; k++) {
                                 if (result > cWays[k]) {
                                     result -= cWays[k];
                                 } else {
                                     done[k] = true;
                                     builder.append(label[k]);
                                     break;
                                 }
                             }
                         }
                         for (int j = 0; j < m; j++) {
                             if (builder.toString().contains(words[j])) {
                                 answer[j] += 1d / BUBEN;
                             }
                         }
                     }
                 }

                 private double calculate(int at) {
                     if (ways[at] != -1) {
                         return ways[at];
                     }
                     ways[at] = 1;
                     length[at] = 0;
                     for (int i = graph.firstOutbound(at); i != -1; i = graph.nextOutbound(i)) {
                         int j = graph.destination(i);
                         ways[at] *= calculate(j);
                         ways[at] *= c[length[at] + length[j]][length[j]];
                         length[at] += length[j];
                     }
                     length[at]++;
                     return ways[at];
                 }


                 public void write(OutputWriter out, int testNumber) {
                     out.print("Case #" + testNumber + ": ");
                     out.printLine(answer);
                 }
             }, 4);
         }

     }

     static class Scheduler {
         private final AtomicInteger testsRemaining;
         private final AtomicInteger threadsRemaining;

         public Scheduler(InputReader in, OutputWriter out, TaskFactory factory, int numParallel) {
             try {
                 testsRemaining = new AtomicInteger(in.readInt());
                 threadsRemaining = new AtomicInteger(numParallel);
                 Task[] tasks = new Task[testsRemaining.get()];
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i] = factory.newTask();
                 }
                 for (Task task : tasks) {
                     task.read(in);
                     new Thread(() -> {
                         boolean freeThread = false;
                         synchronized (this) {
                             do {
                                 try {
                                     wait(10);
                                 } catch (InterruptedException ignored) {
                                 }
                                 if (threadsRemaining.get() != 0) {
                                     synchronized (threadsRemaining) {
                                         if (threadsRemaining.get() != 0) {
                                             threadsRemaining.decrementAndGet();
                                             freeThread = true;
                                         }
                                     }
                                 }
                             } while (!freeThread);
                         }
                         task.solve();
                         System.err.println(testsRemaining.decrementAndGet());
                         threadsRemaining.incrementAndGet();
                     }).start();
                 }
                 synchronized (this) {
                     while (testsRemaining.get() > 0) {
                         wait(10);
                     }
                 }
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i].write(out, i + 1);
                 }
             } catch (InterruptedException e) {
                 throw new RuntimeException(e);
             }
         }

     }

     static class OutputWriter {
         private final PrintWriter writer;

         public OutputWriter(OutputStream outputStream) {
             writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
         }

         public OutputWriter(Writer writer) {
             this.writer = new PrintWriter(writer);
         }

         public void print(Object... objects) {
             for (int i = 0; i < objects.length; i++) {
                 if (i != 0) {
                     writer.print(' ');
                 }
                 writer.print(objects[i]);
             }
         }

         public void print(double[] array) {
             for (int i = 0; i < array.length; i++) {
                 if (i != 0) {
                     writer.print(' ');
                 }
                 writer.print(array[i]);
             }
         }

         public void printLine(double[] array) {
             print(array);
             writer.println();
         }

         public void close() {
             writer.close();
         }

     }

     static interface Task {
         public void read(InputReader in);

         public void solve();

         public void write(OutputWriter out, int testNumber);

     }

     static interface TaskFactory {
         public Task newTask();

     }

     static interface Edge {
     }

     static class InputReader {
         private InputStream stream;
         private byte[] buf = new byte[1024];
         private int curChar;
         private int numChars;
         private InputReader.SpaceCharFilter filter;

         public InputReader(InputStream stream) {
             this.stream = stream;
         }

         public int read() {
             if (numChars == -1) {
                 throw new InputMismatchException();
             }
             if (curChar >= numChars) {
                 curChar = 0;
                 try {
                     numChars = stream.read(buf);
                 } catch (IOException e) {
                     throw new InputMismatchException();
                 }
                 if (numChars <= 0) {
                     return -1;
                 }
             }
             return buf[curChar++];
         }

         public int readInt() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             int sgn = 1;
             if (c == '-') {
                 sgn = -1;
                 c = read();
             }
             int res = 0;
             do {
                 if (c < '0' || c > '9') {
                     throw new InputMismatchException();
                 }
                 res *= 10;
                 res += c - '0';
                 c = read();
             } while (!isSpaceChar(c));
             return res * sgn;
         }

         public String readString() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             StringBuilder res = new StringBuilder();
             do {
                 if (Character.isValidCodePoint(c)) {
                     res.appendCodePoint(c);
                 }
                 c = read();
             } while (!isSpaceChar(c));
             return res.toString();
         }

         public boolean isSpaceChar(int c) {
             if (filter != null) {
                 return filter.isSpaceChar(c);
             }
             return isWhitespace(c);
         }

         public static boolean isWhitespace(int c) {
             return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
         }

         public char readCharacter() {
             int c = read();
             while (isSpaceChar(c)) {
                 c = read();
             }
             return (char) c;
