     static class TaskD {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
                 int n;
                 long[] x;
                 long[] y;
                 long[] z;


                 public void read(InputReader in) {
                     n = in.readInt();
                     x = new long[n];
                     y = new long[n];
                     z = new long[n];
                     IOUtils.readLongArrays(in, x, y, z);
                 }

                 boolean answer;


                 public void solve() {
                     answer = true;
                     for (int i = 0; i < n; i++) {
                         for (int j = 0; j < i; j++) {
                             long a = y[j] * z[i] - z[j] * y[i];
                             long b = -z[i] * x[j] + z[j] * x[i];
                             long c = y[i] * x[j] - y[j] * x[i];
                             if (a == 0 && b == 0 && c == 0) {
                                 if (Long.signum(x[i]) != Long.signum(x[j])) {
                                     return;
                                 }
                                 if (Long.signum(y[i]) != Long.signum(y[j])) {
                                     return;
                                 }
                                 if (Long.signum(z[i]) != Long.signum(z[j])) {
                                     return;
                                 }
                             }

                         }
                     }
                     for (int i = 0; i < n; i++) {
                         for (int j = 0; j < i; j++) {
                             long a = y[j] * z[i] - z[j] * y[i];
                             long b = -z[i] * x[j] + z[j] * x[i];
                             long c = y[i] * x[j] - y[j] * x[i];
                             if (a == 0 && b == 0 && c == 0) {
                                 continue;
                             }
                             if (a * x[i] + b * y[i] + c * z[i] != 0) {
                                 throw new RuntimeException();
                             }
                             if (a * x[j] + b * y[j] + c * z[j] != 0) {
                                 throw new RuntimeException();
                             }
                             boolean up = false;
                             boolean down = false;
                             IntList touch = new IntArrayList();
                             boolean willDoLater = false;
                             for (int k = 0; k < n; k++) {
                                 if (i == k || j == k || same(i, k) || same(j, k)) {
                                     continue;
                                 }
                                 long value = x[k] * a + y[k] * b + z[k] * c;
                                 if (value > 0) {
                                     up = true;
                                 }
                                 if (value < 0) {
                                     down = true;
                                 }
                                 if (value == 0) {
                                     if (k > j) {
                                         willDoLater = true;
                                     } else {
                                         touch.add(k);
                                     }
                                 }
                             }
                             if ((!up || !down) && touch.isEmpty() && !willDoLater) {
                                 answer = false;
                                 return;
                             }
                             if (willDoLater || touch.isEmpty()) {
                                 continue;
                             }
                             if (up && down) {
                                 continue;
                             }
                             touch.add(i);
                             touch.add(j);
                             for (int k = 0; k < touch.size(); k++) {
                                 int id = touch.get(k);
                                 BigInteger a0 = BigInteger.valueOf(y[id] * c - z[id] * b);
                                 BigInteger b0 = BigInteger.valueOf(-c * x[id] + z[id] * a);
                                 BigInteger c0 = BigInteger.valueOf(b * x[id] - y[id] * a);
                                 up = false;
                                 down = false;
                                 for (int l = 0; l < touch.size(); l++) {
                                     if (k == l) {
                                         continue;
                                     }
                                     id = touch.get(l);
                                     BigInteger value = a0.multiply(BigInteger.valueOf(x[id])).add(b0.multiply(BigInteger
                                             .valueOf(y[id]))).add(c0.multiply(BigInteger.valueOf(z[id])));
                                     if (value.signum() > 0) {
                                         up = true;
                                     }
                                     if (value.signum() < 0) {
                                         down = true;
                                     }
                                 }
                                 if (!up || !down) {
                                     answer = false;
                                     return;
                                 }
                             }
                         }
                     }
                 }

                 private boolean same(int i, int j) {
                     long a = y[j] * z[i] - z[j] * y[i];
                     long b = -z[i] * x[j] + z[j] * x[i];
                     long c = y[i] * x[j] - y[j] * x[i];
                     return a == 0 && b == 0 && c == 0;
                 }


                 public void write(OutputWriter out, int testNumber) {
                     out.printLine("Case #" + testNumber + ":", answer ? "YES" : "NO");
                 }
             }, 23);
         }

     }

     static abstract class IntAbstractStream implements IntStream {

         public String toString() {
             StringBuilder builder = new StringBuilder();
             boolean first = true;
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 if (first) {
                     first = false;
                 } else {
                     builder.append(' ');
                 }
                 builder.append(it.value());
             }
             return builder.toString();
         }


         public boolean equals(Object o) {
             if (!(o instanceof IntStream)) {
                 return false;
             }
             IntStream c = (IntStream) o;
             IntIterator it = intIterator();
             IntIterator jt = c.intIterator();
             while (it.isValid() && jt.isValid()) {
                 if (it.value() != jt.value()) {
                     return false;
                 }
                 it.advance();
                 jt.advance();
             }
             return !it.isValid() && !jt.isValid();
         }


         public int hashCode() {
             int result = 0;
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 result *= 31;
                 result += it.value();
             }
             return result;
         }

     }

     static class IntArrayList extends IntAbstractStream implements IntList {
         private int size;
         private int[] data;

         public IntArrayList() {
             this(3);
         }

         public IntArrayList(int capacity) {
             data = new int[capacity];
         }

         public IntArrayList(IntCollection c) {
             this(c.size());
             addAll(c);
         }

         public IntArrayList(IntStream c) {
             this();
             if (c instanceof IntCollection) {
                 ensureCapacity(((IntCollection) c).size());
             }
             addAll(c);
         }

         public IntArrayList(IntArrayList c) {
             size = c.size();
             data = c.data.clone();
         }

         public IntArrayList(int[] arr) {
             size = arr.length;
             data = arr.clone();
         }

         public int size() {
             return size;
         }

         public int get(int at) {
             if (at >= size) {
                 throw new IndexOutOfBoundsException("at = " + at + ", size = " + size);
             }
             return data[at];
         }

         private void ensureCapacity(int capacity) {
             if (data.length >= capacity) {
                 return;
             }
             capacity = Math.max(2 * data.length, capacity);
             data = Arrays.copyOf(data, capacity);
         }

         public void addAt(int index, int value) {
             ensureCapacity(size + 1);
             if (index > size || index < 0) {
                 throw new IndexOutOfBoundsException("at = " + index + ", size = " + size);
             }
             if (index != size) {
                 System.arraycopy(data, index, data, index + 1, size - index);
             }
             data[index] = value;
             size++;
         }

         public void removeAt(int index) {
             if (index >= size || index < 0) {
                 throw new IndexOutOfBoundsException("at = " + index + ", size = " + size);
             }
             if (index != size - 1) {
                 System.arraycopy(data, index + 1, data, index, size - index - 1);
             }
             size--;
         }

     }

