public class A {
    int n;

    static long solve(int n) {
        if (n == 0) {
            return 0;
        }
        Set<Character> set = new TreeSet<>();
        for (long i = n;; i += n) {
            String s = "" + i;
            for (int j = 0; j < s.length(); j++) {
                set.add(s.charAt(j));
            }
            if (set.size() == 10) {
                return i;
            }
        }
    }

    String solve() {
        long ans = solve(n);
        return ans == 0 ? "INSOMNIA" : "" + ans;
    }

    public A(Scanner in) {
        n = in.nextInt();
    }

    static void check() {
        for (int n = 1; n <= 1_000_000; n++) {
            solve(n);
        }
    }

