        for (int i = 0; i < hei; i++) {
            for (int j = 0; j < wid; j++) {
                long v = Long.MAX_VALUE;
                for (int k = 0; k < n; k++) {
                    int dist = Math.abs(i - x[k]) + Math.abs(j - y[k]);
                    v = Math.min(v, b[k] + dist * 1L * d);
                }
                for (int k = 0; k < n; k++) {
                    int dist = Math.abs(i - x[k]) + Math.abs(j - y[k]);
                    if (dist == 0 && v < b[k]) {
